    total_reviews integer DEFAULT 0 NOT NULL,
    pending_reviews integer DEFAULT 0 NOT NULL,
    processing_reviews integer DEFAULT 0 NOT NULL,
    analyzed_reviews integer DEFAULT 0 NOT NULL,
    failed_reviews integer DEFAULT 0 NOT NULL,
    findings_created integer DEFAULT 0 NOT NULL,
    needs_aggregation_rebuild boolean DEFAULT true NOT NULL,
    needs_snapshot_rebuild boolean DEFAULT true NOT NULL,
    last_review_analyzed_at timestamp with time zone,
    last_recalculated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT daily_review_understanding_non_negative CHECK (((total_reviews >= 0) AND (pending_reviews >= 0) AND (processing_reviews >= 0) AND (analyzed_reviews >= 0) AND (failed_reviews >= 0) AND (findings_created >= 0))),
    CONSTRAINT daily_review_understanding_status_total CHECK ((total_reviews = (((pending_reviews + processing_reviews) + analyzed_reviews) + failed_reviews)))
);


