--
-- Name: dynamic_profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dynamic_profiles (
    id bigint NOT NULL,
    profile_name text NOT NULL,
    description text,
    version integer DEFAULT 1 NOT NULL,
    criticality numeric(5,4) DEFAULT 1.0000 NOT NULL,
    negative_sensitivity numeric(6,4) DEFAULT 1.0000 NOT NULL,
    positive_sensitivity numeric(6,4) DEFAULT 1.0000 NOT NULL,
    negative_threshold numeric(6,2) DEFAULT 45.00 NOT NULL,
    positive_threshold numeric(6,2) DEFAULT 80.00 NOT NULL,
    negative_convergence numeric(6,2) DEFAULT 55.00 NOT NULL,
    positive_convergence numeric(6,2) DEFAULT 82.00 NOT NULL,
    negative_lambda numeric(8,6) DEFAULT 0.060000 NOT NULL,
    positive_lambda numeric(8,6) DEFAULT 0.020000 NOT NULL,
    max_negative_daily_change numeric(6,2) DEFAULT 20.00 NOT NULL,
    max_positive_daily_change numeric(6,2) DEFAULT 12.00 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dynamic_profiles_criticality_check CHECK (((criticality >= (0)::numeric) AND (criticality <= (1)::numeric))),
    CONSTRAINT dynamic_profiles_negative_change_check CHECK ((max_negative_daily_change >= (0)::numeric)),
    CONSTRAINT dynamic_profiles_negative_convergence_check CHECK (((negative_convergence >= (0)::numeric) AND (negative_convergence <= (100)::numeric))),
    CONSTRAINT dynamic_profiles_negative_lambda_check CHECK ((negative_lambda >= (0)::numeric)),
    CONSTRAINT dynamic_profiles_negative_threshold_check CHECK (((negative_threshold >= (0)::numeric) AND (negative_threshold <= (100)::numeric))),
    CONSTRAINT dynamic_profiles_positive_change_check CHECK ((max_positive_daily_change >= (0)::numeric)),
    CONSTRAINT dynamic_profiles_positive_convergence_check CHECK (((positive_convergence >= (0)::numeric) AND (positive_convergence <= (100)::numeric))),
    CONSTRAINT dynamic_profiles_positive_lambda_check CHECK ((positive_lambda >= (0)::numeric)),
    CONSTRAINT dynamic_profiles_positive_threshold_check CHECK (((positive_threshold >= (0)::numeric) AND (positive_threshold <= (100)::numeric))),
    CONSTRAINT dynamic_profiles_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'experimental'::text, 'deprecated'::text]))),
    CONSTRAINT dynamic_profiles_threshold_order_check CHECK ((negative_threshold < positive_threshold))
);


ALTER TABLE public.dynamic_profiles OWNER TO postgres;

